def longestDuplicateLength(s):
    n = len(s)
    MOD = (1 << 61) - 1
    BASE = 911382323
    vals = [ord(c) for c in s]

    def has_dup(L):
        h = 0
        for i in range(L):
            h = (h * BASE + vals[i]) % MOD
        top = pow(BASE, L - 1, MOD)
        seen = {h: [0]}
        for i in range(1, n - L + 1):
            h = ((h - vals[i - 1] * top) * BASE + vals[i + L - 1]) % MOD
            if h in seen:
                sub = s[i:i + L]
                for j in seen[h]:
                    if s[j:j + L] == sub:
                        return True
                seen[h].append(i)
            else:
                seen[h] = [i]
        return False

    lo, hi = 0, n - 1
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if has_dup(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo
